local Utility = {}
do -- Utility
    function Utility.NewDrawing(Type, Props, Location)
        local draw = Drawing.new(Type)
        for index, value in pairs(Props) do
            draw[index] = value
        end
        Location = Location or Library.Drawings

        Location[#Location + 1] = draw

        return draw
    end

    function Utility.DelDrawing(Draw, Location)
        Location = Location or Library.Drawings
        local index = table.find(Location, Draw)
        Location[index]:Destroy()
        table.remove(Location, index)
    end

    function Utility.AddConnection(Target, Callback)
        local cnct
        cnct = Target:Connect(Callback)
        Library.Connections[#Library.Connections] = cnct

        return cnct
    end

    function Utility.DelConnection(Target)
        -- ::: TODO
    end

    function Utility.RandomString(length)
        local random = Random.new()
        local letters = {'a','b','c','d','e','f','g','h','i','j','k','l','m','n','o','p','q','r','s','t','u','v','w','x','y','z'}

        length = length or 10
        local str = ''
        for i=1, length do
            local randLetter = letters[random:NextInteger(1,#letters)]
            if random:NextNumber() > .5 then
                randLetter = string.upper(randLetter)
            end
            str = str..randLetter
        end

        return str
    end

    function Utility.HSV2RGB(hsv)
        return Color3.fromRGB(hsv.r*255, hsv.g*255, hsv.b*255)
    end

    function Utility.MouseOver(Object, dropdown)
        dropdown = dropdown or false
        local Mouse = UserInputService:GetMouseLocation()
        if Object.Visible and (Mouse.X > Object.Position.X) and (Mouse.X < Object.Position.X + Object.Size.X) and (Mouse.Y > Object.Position.Y) and (Mouse.Y < Object.Position.Y + Object.Size.Y) then
            if dropdown == false then
                if Library.WindowVisible and not Library.DropdownOpen then
                    return true
                end
            else
                if Library.WindowVisible then
                    return true
                end
            end
        end
    end

    function Utility.AddDrag(Sensor, List)
        local DragUtil = {
            MouseStart = Vector2.new(), MouseEnd = Vector2.new(), Dragging = false
        }

        Utility.AddConnection(UserInputService.InputBegan, function(Input)
            if Input.UserInputType == Enum.UserInputType.MouseButton1 then
                if Utility.MouseOver(Sensor) then
                    DragUtil.Dragging = true
                end
            end
        end)

        Utility.AddConnection(UserInputService.InputEnded, function(Input)
            if Input.UserInputType == Enum.UserInputType.MouseButton1 then
                DragUtil.Dragging = false
            end
        end)

        Utility.AddConnection(RunService.RenderStepped, function()
            DragUtil.MouseStart = UserInputService:GetMouseLocation()

            for index, value in pairs(List) do
                if index ~= nil and value ~= nil then
                    if DragUtil.Dragging then
                        value.Position = Vector2.new(
                            value.Position.X + (DragUtil.MouseStart.X - DragUtil.MouseEnd.X),
                            value.Position.Y + (DragUtil.MouseStart.Y - DragUtil.MouseEnd.Y)
                        )
                    end
                end
            end
            
            DragUtil.MouseEnd = UserInputService:GetMouseLocation()
        end)
    end

    function Utility.DrawCursor()
        local CursorOutline = Utility.NewDrawing("Triangle", {
            Color = Library.Theme.Outline,
            Visible = false,
            Thickness = 1,
            Transparency = 1,
            Filled = false,
            ZIndex = 50,
        }, Library.Special.Cursor)

        local CursorFill = Utility.NewDrawing("Triangle", {
            Color = Library.Theme.Accent[1],
            Visible = false,
            Thickness = 1,
            Transparency = 1,
            Filled = true,
            ZIndex = 50,
        }, Library.Special.Cursor)
        Utility.AddConnection(RunService.RenderStepped, function()
            local Mouse = UserInputService:GetMouseLocation()
            if Library.WindowVisible then
                CursorOutline.Visible = true
                CursorOutline.PointA = Vector2.new(Mouse.X, Mouse.Y)
                CursorOutline.PointB = Vector2.new(Mouse.X + 12, Mouse.Y + 4)
                CursorOutline.PointC = Vector2.new(Mouse.X + 4, Mouse.Y + 12)

                CursorFill.Visible = true
                CursorFill.PointA = Vector2.new(Mouse.X, Mouse.Y)
                CursorFill.PointB = Vector2.new(Mouse.X + 12, Mouse.Y + 4)
                CursorFill.PointC = Vector2.new(Mouse.X + 4, Mouse.Y + 12)
            else
                CursorOutline.Visible = false
                CursorFill.Visible = false
            end
        end)
    end

    function Utility.GetMiddle(Object)
        return Vector2.new(
            (Camera.ViewportSize.X/2) - (Object.Size.X/2),
            (Camera.ViewportSize.Y/2) - (Object.Size.Y/2)
        )
    end

    function Utility.ParseTriggers(text)
        local triggers = {
                ['{hour}'] = os.date("%H"),
                ['{minute}'] = os.date("%M"),
                ['{second}'] = os.date("%S"),
                ['{ap}'] = os.date("%p"),
                ['{month}'] = os.date("%b"),
                ['{day}'] = os.date("%d"),
                ['{year}'] = os.date("%Y"),
                ['{fps}'] = game:GetService('Stats').FrameRateManager:FindFirstChild('RenderAverage') and string.format('%.1f', 1000 / game:GetService('Stats').FrameRateManager.RenderAverage:GetValue())..' fps' or '0 fps',
                ['{ping}'] = game:GetService('Stats') ~= nil and math.floor(game:GetService('Stats').Network.ServerStatsItem["Data Ping"]:GetValue())..' ms' or "0 ms",
                ['{game}'] = game.GameId,
                ['{build}'] = "dev",
                ['{uid}'] = getgenv().uid or 1,
                ['{time}'] = os.date('%X', os.time()),
                ['{date}'] = os.date("%b. %d, %Y"),
                ['{subtime}'] = tostring(getgenv().subtime).."d" or tostring(30).."d"
                }

        for index, value in next, triggers do
            text = string.gsub(text, index, value)
        end

        return text
    end

    function Utility.Lerp(start, finish, speed)
        return start + (finish - start) * speed
    end
end

do -- Watermark
    function Library:RenderWatermark(props)
        props.Text = props.Text or "nil"
        props.Drag = props.Drag or false
        props.Position = props.Position or Vector2.new(50, 50)
        local Watermark = {}
        
        local WMOutline = Utility.NewDrawing("Square", {
                Visible = true,
                Transparency = 1,
                Color = Library.Theme.Outline,
                Size = Vector2.new(370, 20),
                Position = props.Position,
                Filled = true,
        }, Library.Watermark)
    
        local WMInline = Utility.NewDrawing("Square", {
            Visible = true,
            Transparency = 1,
            Color = Library.Theme.Inline,
            Size = WMOutline.Size+Vector2.new(-2, -2),
            Position = WMOutline.Position+Vector2.new(1, 1),
            Filled = true,
        }, Library.Watermark)
    
        local WMBackground = Utility.NewDrawing("Square", {
            Visible = true,
            Transparency = 1,
            Color = Library.Theme.Background,
            Size = WMInline.Size+Vector2.new(-2, -2),
            Position = WMInline.Position+Vector2.new(1, 1),
            Filled = true,
        }, Library.Watermark)
    
        local WMText = Utility.NewDrawing("Text", {
            Font = Library.Theme.Font,
            Size = Library.Theme.TextSize,
            Color = Library.Theme.DarkWhite,
            Position = WMBackground.Position + Vector2.new(5, 2),
            Center = false,
            Outline = true,
            Visible = true,
            Transparency = 1
        }, Library.Watermark)

        if props.Drag then
            Utility.AddDrag(WMBackground, Library.Watermark)
        end

        local con = Utility.AddConnection(RunService.RenderStepped, function()
            WMText.Text = Utility.ParseTriggers(props.Text)
            WMOutline.Size = Vector2.new(WMText.TextBounds.X+15, 20)
            WMInline.Size = WMOutline.Size+Vector2.new(-2, -2)
            WMBackground.Size = WMInline.Size+Vector2.new(-2, -2)
        end)

        function Watermark:SetVisible(bool)
            bool = bool or not WMBackground.Visible
            for i,v in pairs(Library.Watermark) do
                v.Visible = bool
            end
        end

        function Watermark:SetText(text)
            props.Text = text
        end

        function Watermark:Destroy()
            local index = table.find(Library.Connections, con)
            con:Disconnect()

            local OutIdx = table.find(Library.Watermark, WMOutline)
            local InIdx = table.find(Library.Watermark, WMInline)
            local BGIdx = table.find(Library.Watermark, WMBackground)
            local TxtIdx = table.find(Library.Watermark, WMText)
            WMOutline:Destroy()
            WMInline:Destroy()
            WMBackground:Destroy()
            WMText:Destroy()

            table.remove(Library.Connections, OutIdx)
            table.remove(Library.Connections, InIdx)
            table.remove(Library.Connections, BGIdx)
            table.remove(Library.Connections, TxtIdx)

            table.remove(Library.Connections, index)
        end

        return Watermark
    end
end

do -- Loader
    function Library:RenderLoader(props)
        props.Name = props.Name or "name"
        props.Size = props.Size or Vector2.new(300, 300)
        local Loader = {}
        Library.LoaderDone = false

        local LoaderOutline = Utility.NewDrawing("Square", {
            Visible = true,
            Transparency = 1,
            Color = Library.Theme.Outline,
            Size = props.Size,
            Filled = true,
        }, Library.Special.Loader)
        LoaderOutline.Position = Utility.GetMiddle(LoaderOutline)

        local LoaderInline = Utility.NewDrawing("Square", {
            Visible = true,
            Transparency = 1,
            Color = Library.Theme.Inline,
            Size = LoaderOutline.Size+Vector2.new(-2, -2),
            Position = LoaderOutline.Position+Vector2.new(1, 1),
            Filled = true,
        }, Library.Special.Loader)

        local LoaderBackground = Utility.NewDrawing("Square", {
            Visible = true,
            Transparency = 1,
            Color = Library.Theme.DarkContrast,
            Size = LoaderInline.Size+Vector2.new(-2, -2),
            Position = LoaderInline.Position+Vector2.new(1, 1),
            Filled = true,
        }, Library.Special.Loader)

        local LoaderImage = Utility.NewDrawing("Image", {
            Visible = true,
            Transparency = 1,
            Data = Library.Images.Logo,
            Position = LoaderBackground.Position,
            Size = LoaderBackground.Size
        }, Library.Special.Loader)

        local LoaderText = Utility.NewDrawing("Text", {
            Font = Library.Theme.Font,
            Size = Library.Theme.TextSize,
            Color = Library.Theme.DarkWhite,
            Position = LoaderImage.Position + Vector2.new(LoaderImage.Size.X/2, LoaderImage.Size.Y - 50),
            Center = true,
            Outline = true,
            Visible = true,
            Transparency = 1
        }, Library.Special.Loader)

        LoaderText.Text = "loading..."

        function Loader:SetText(text)
            LoaderText.Text = text
        end

        function Loader:SetColor(Color)
            LoaderText.Color = Color
        end

        function Loader:FadeOut()

            task.spawn(function()
                for i = 1, 0, -0.01 do
                    task.wait()
                    LoaderOutline.Transparency = LoaderOutline.Transparency - 0.01
                end

                Library.LoaderDone = true
            end)
            task.spawn(function()
                for i = 1, 0, -0.01 do
                    task.wait()
                    LoaderInline.Transparency = LoaderInline.Transparency - 0.01
                end
            end)
            task.spawn(function()
                for i = 1, 0, -0.01 do
                    task.wait()
                    LoaderBackground.Transparency = LoaderBackground.Transparency - 0.01
                end
            end)
            task.spawn(function()
                for i = 1, 0, -0.01 do
                    task.wait()
                    LoaderImage.Transparency = LoaderImage.Transparency - 0.01
                end
            end)
            task.spawn(function()
                for i = 1, 0, -0.01 do
                    task.wait()
                    LoaderText.Transparency = LoaderText.Transparency - 0.01
                end
            end)
        end

        local LoaderWatermark = Library:RenderWatermark({Drag = false, Text = "lsd.xyz   |   simply better", Position = Vector2.new(LoaderOutline.Position.X + (LoaderOutline.Size.X/2) - 65, LoaderOutline.Position.Y + 5)})

        task.spawn(function()
            Loader:SetText("checking images...")
            for i,v in pairs(Library.Images) do
                if i ~= nil and v ~= nil then
                else
                    Loader:SetText("failed to load images!")
                    Loader:SetColor(Color3.fromRGB(255, 0, 0))
                end
            end
            Loader:SetColor(Library.Theme.DarkWhite)
            Loader:SetText("checking skibidi...")
            task.wait(2)
            Loader:SetColor(Color3.fromRGB(255, 0, 0))
            Loader:SetText("attempting to terminate skibidi...")
            task.wait(1)
            Loader:SetColor(Color3.fromRGB(0, 255, 0))
            Loader:SetText("skibidi removed...")
            task.wait(1)
            Loader:SetColor(Library.Theme.DarkWhite)
            Loader:SetText("enjoy!")
            task.wait(2)
            Loader:FadeOut()
            LoaderWatermark:Destroy()

            
        end)

        return Loader
    end
end

