                for i,v in pairs(Window.Tabs) do
                    tab.Selected = true
                    tab.Drawings.TabText.Color = Library.Theme.Accent[1]
                    tab.Drawings.TabBackground.Color = Library.Theme.Background
                    for a,b in pairs(tab.Elements) do
                        b.Visible = true
                    end
                    if v ~= tab then
                        if v ~= tab then
                            v.Selected = false
                            v.Drawings.TabText.Color = Library.Theme.DarkGrey
                            v.Drawings.TabBackground.Color = Library.Theme.DarkContrast
                            for a,b in pairs(v.Elements) do
                                b.Visible = false
                            end
                        end
                    end
                end
            end
        end
        function Window:Tab(props)
            props.Name = props.Name or "tab"
            local Tab = {
                Drawings = {},
                Elements = {},
                Sections = { -- Section table format = {name, sizeY, drawings}
                    Left = 0,
                    Right = 0
                },
                Selected = #Window.Tabs == 0 or false
            }

            local TabOutline = Utility.NewDrawing("Square", {
                Visible = true,
                Transparency = 1,
                Color = Library.Theme.Outline,
                Size = Vector2.new(TabbarBackground.Size.X, 25),
                Position = TabbarBackground.Position + Vector2.new(0, 25*#Window.Tabs),
                Filled = true,
            })
            Tab.Drawings.TabOutline = TabOutline
    
            local TabInline = Utility.NewDrawing("Square", {
                Visible = true,
                Transparency = 1,
                Color = Library.Theme.Inline,
                Size = TabOutline.Size+Vector2.new(-2, -2),
                Position = TabOutline.Position+Vector2.new(1, 1),
                Filled = true,
            })
            Tab.Drawings.TabInline = TabInline
    
            local TabBackground = Utility.NewDrawing("Square", {
                Visible = true,
                Transparency = 1,
                Color = Library.Theme.DarkContrast,
                Size = TabInline.Size+Vector2.new(-2, -2),
                Position = TabInline.Position+Vector2.new(1, 1),
                Filled = true,
            })
            Tab.Drawings.TabBackground = TabBackground

            local TabGradient = Utility.NewDrawing("Image", {
                Visible = true,
                Transparency = 1,
                Color = Library.Theme.DarkContrast,
                Size = TabInline.Size+Vector2.new(-2, -2),
                Position = TabInline.Position+Vector2.new(1, 1),
                Data = Library.Images.GradientDown,
            })
            Tab.Drawings.TabGradient = TabGradient

            local TabText = Utility.NewDrawing("Text", {
                Font = Library.Theme.Font,
                Size = Library.Theme.TextSize,
                Color = Library.Theme.DarkGrey,
                Center = false,
                Outline = true,
                Visible = true,
                Transparency = 1
            })
            Tab.Drawings.TabText = TabText
            TabText.Text = props.Name
            TabText.Position = TabBackground.Position + Vector2.new((TabBackground.Size.X/2) - (TabText.TextBounds.X/2), 5)

            -- << Detect clicks >>
            Utility.AddConnection(UserInputService.InputBegan, function(Input)
                if Input.UserInputType == Enum.UserInputType.MouseButton1 and Utility.MouseOver(TabOutline) then
                    Window:SwitchTab(Tab)
                end
            end)

            function Tab:Section(props)
                props.Name = props.Name or "section"
                props.Side = props.Side or "Left"
                props.Size = props.Size or Vector2.new(0, 20)
                local Section = {
                    Drawings = {},
                    ContentSize = 0
                }

                local SectionX = props.Side == "Left" and ContentHolderBackground.Position.X or ContentHolderBackground.Position.X + ((ContentHolderBackground.Size.X / 2)) + 3

                local SectionOutline = Utility.NewDrawing("Square", {
                    Visible = false,
                    Transparency = 1,
                    Color = Library.Theme.Outline,
                    Size = Vector2.new(ContentHolderBackground.Size.X/2 - 3, 0) + props.Size,
                    Position = Vector2.new(SectionX, (Tab.Sections[props.Side] == 0 and ContentHolderBackground.Position.Y + 5 or Tab.Sections[props.Side] + ContentHolderBackground.Position.Y + 5)),
                    Filled = true,
                })
                Section.Drawings.SectionOutline = SectionOutline
        
                local SectionInline = Utility.NewDrawing("Square", {
                    Visible = false,
                    Transparency = 1,
                    Color = Library.Theme.Inline,
                    Size = SectionOutline.Size+Vector2.new(-2, -2),
                    Position = SectionOutline.Position+Vector2.new(1, 1),
                    Filled = true,
                })
                Section.Drawings.SectionInline = SectionInline
        
                local SectionBackground = Utility.NewDrawing("Square", {
                    Visible = false,
                    Transparency = 1,
                    Color = Library.Theme.DarkContrast,
                    Size = SectionInline.Size+Vector2.new(-2, -2),
                    Position = SectionInline.Position+Vector2.new(1, 1),
                    Filled = true,
                })
                Section.Drawings.SectionBackground = SectionBackground

                local SectionAccent = Utility.NewDrawing("Square", {
                    Visible = false,
                    Transparency = 1,
                    Color = Library.Theme.Accent[1],
                    Size = Vector2.new(SectionBackground.Size.X, 1),
                    Position = SectionBackground.Position,
                    Filled = true,
                })
                Section.Drawings.SectionAccent = SectionAccent

                local SectionText = Utility.NewDrawing("Text", {
                    Font = Library.Theme.Font,
                    Size = Library.Theme.TextSize,
                    Color = Library.Theme.DarkWhite,
                    Center = false,
                    Outline = true,
                    Visible = false,
                    Transparency = 1
                })
                Section.Drawings.SectionText = SectionText
                SectionText.Text = props.Name
                SectionText.Position = Vector2.new(SectionBackground.Position.X + (SectionBackground.Size.X / 2) - (SectionText.TextBounds.X / 2), SectionBackground.Position.Y + 2)

                function Section:UpdateSizeY(sizeY)
                    SectionOutline.Size = Vector2.new(SectionOutline.Size.X, sizeY + 5)

                    SectionInline.Size = Vector2.new(SectionOutline.Size.X - 2, SectionOutline.Size.Y - 2)
                    SectionInline.Position = Vector2.new(SectionOutline.Position.X + 1, SectionOutline.Position.Y + 1)

                    SectionBackground.Size = Vector2.new(SectionInline.Size.X - 2, SectionInline.Size.Y - 2)
                    SectionBackground.Position = Vector2.new(SectionInline.Position.X + 1, SectionInline.Position.Y + 1)
                end

                function Section:Toggle(eprops)
                    eprops.Name = eprops.Name or "button"
                    eprops.Callback = eprops.Callback or function() end
                    eprops.Default = eprops.Default or false
                    eprops.Flag = eprops.Flag or Utility.RandomString(15)
                    eprops.Color = eprops.Color or Library.Theme.DarkWhite
                    local Toggle = {
                        Axis = Section.ContentSize,
                        Drawings = {},
                        Toggled = eprops.Default
                    }

                    local ToggleOutline = Utility.NewDrawing("Square", {
                        Position = Vector2.new(SectionBackground.Position.X + 8, SectionBackground.Position.Y + 15 + Toggle.Axis),
                        Size = Vector2.new(10, 10),
                        Thickness = 0,
                        Color = Library.Theme.Outline,
                        Visible = false,
                        Filled = true
                    })
                    Toggle.Drawings.ToggleOutline = ToggleOutline

                    local ToggleInline = Utility.NewDrawing("Square", {
                        Visible = false,
                        Transparency = 1,
                        Color = Library.Theme.Inline,
                        Size = ToggleOutline.Size+Vector2.new(-2, -2),
                        Position = ToggleOutline.Position+Vector2.new(1, 1),
                        Filled = true,
                    })
                    Toggle.Drawings.ToggleInline = ToggleInline
            
                    local ToggleBackground = Utility.NewDrawing("Square", {
                        Visible = false,
                        Transparency = 1,
                        Color = Library.Theme.DarkContrast,
                        Size = ToggleInline.Size+Vector2.new(-2, -2),
                        Position = ToggleInline.Position+Vector2.new(1, 1),
                        Filled = true,
                    })
                    Toggle.Drawings.ToggleBackground = ToggleBackground

                    local ToggleGradient = Utility.NewDrawing("Image", {
                        Visible = false,
                        Transparency = 1,
                        Size = ToggleInline.Size+Vector2.new(-2, -2),
                        Position = ToggleInline.Position+Vector2.new(1, 1),
                        Data = Library.Images.GradientDown
                    })
                    Toggle.Drawings.ToggleGradient = ToggleGradient

                    local ToggleText = Utility.NewDrawing("Text", {
                        Font = Library.Theme.Font,
                        Size = Library.Theme.TextSize,
                        Color = eprops.Color,
                        Text = eprops.Name,
                        Position = Vector2.new(ToggleOutline.Position.X + ToggleOutline.Size.X + 5, ToggleOutline.Position.Y ),
                        Center = false,
                        Outline = true,
                        Visible = false,
                        Transparency = 1
                    })
                    Toggle.Drawings.ToggleText = ToggleText

                    ToggleBackground.Color = Toggle.Toggled and Library.Theme.Accent[1] or Library.Theme.DarkContrast
                    if Toggle.Toggled then
                        ToggleText.Color = eprops.Color
                    else
                        ToggleText.Color = eprops.Color == Library.Theme.DarkWhite and Library.Theme.DarkGrey or eprops.Color
                    end

                    Section.ContentSize = Section.ContentSize + ToggleOutline.Size.Y + 8
                    Tab.Sections[props.Side] = Tab.Sections[props.Side] + ToggleOutline.Size.Y + 8 or Tab.Sections[props.Side]

                    self:UpdateSizeY(Section.ContentSize + ToggleOutline.Size.Y + 6)

                    for i,v in pairs(Toggle.Drawings) do
                        Tab.Elements[#Tab.Elements+1] = v
                    end

                    Utility.AddConnection(UserInputService.InputBegan, function(Input)
                        if Input.UserInputType == Enum.UserInputType.MouseButton1 and Utility.MouseOver(ToggleOutline) then
                            Toggle.Toggled = not Toggle.Toggled
                            ToggleBackground.Color = Toggle.Toggled and Library.Theme.Accent[1] or Library.Theme.DarkContrast
                            if Toggle.Toggled then
                                ToggleText.Color = eprops.Color
                            else
                                ToggleText.Color = eprops.Color == Library.Theme.DarkWhite and Library.Theme.DarkGrey or eprops.Color
                            end

                            eprops.Callback(Toggle.Toggled)
                        end
                    end)

                    function Toggle:Get()
                        return Toggle.Toggled
                    end

                    function Toggle:Set(bool)
                        Toggle.Toggled = bool
                        ToggleBackground.Color = Toggle.Toggled and Library.Theme.Accent[1] or Library.Theme.DarkContrast
                        ToggleText.Color = Toggle.Toggled and Library.Theme.DarkWhite or Library.Theme.DarkGrey
                    end

                    function Toggle:Keybind(kprops)
                        kprops.Key = kprops.Key or nil
                        kprops.Callback = kprops.Callback or function() end
                        local Keybind = {
                            Key = kprops.Key,
                            KeyName = kprops.Key ~= nil and kprops.Key.Name or ". . .",
                            Callback = kprops.Callback,
                            Picking = false,
                            State = 0,
                            Drawings = {}
                        }

                        local BindSensor = Utility.NewDrawing("Square", {
                            Visible = false,
                            Transparency = 0,
                            Color = Library.Theme.DarkWhite,
                            Size = Vector2.new(22, 8),
                            Filled = true,
                        })
                        Keybind.Drawings.BindSensor = BindSensor
                        BindSensor.Position = ToggleOutline.Position + Vector2.new((SectionBackground.Size.X/2) + 53, 2)

                        local BindText = Utility.NewDrawing("Text", {
                            Font = Library.Theme.Font,
                            Size = Library.Theme.TextSize,
                            Color = Library.Theme.DarkGrey,
                            Text = "[ "..Keybind.KeyName.." ]",
                            Center = false,
                            Outline = true,
                            Visible = false,
                            Transparency = 1
                        })
                        Keybind.Drawings.BindText = BindText
                        BindText.Position = Vector2.new(BindSensor.Position.X + (BindSensor.Size.X/2) - (BindText.TextBounds.X/2), ToggleText.Position.Y)

                        Utility.AddConnection(UserInputService.InputBegan, function(Input)
                            if Input.UserInputType == Enum.UserInputType.MouseButton1 and Utility.MouseOver(BindSensor) then
                                Keybind.Picking = true
                                BindText.Text = "[ "..". . .".." ]"
                                BindText.Position = Vector2.new(BindSensor.Position.X + (BindSensor.Size.X/2) - (BindText.TextBounds.X/2), ToggleText.Position.Y)
                            end

                            if Keybind.Picking then
                                if Library.Keys.KeyBoard[Input.KeyCode.Name] then
                                    if typeof(Library.Keys.KeyBoard[Input.KeyCode.Name]) ~= "table" then
                                        Keybind.Key = Input.KeyCode
                                        BindText.Text = "[ "..Library.Keys.KeyBoard[Input.KeyCode.Name].." ]"
                                        BindText.Position = Vector2.new(BindSensor.Position.X + (BindSensor.Size.X/2) - (BindText.TextBounds.X/2), ToggleText.Position.Y)
                                        Keybind.Picking = false
                                    else
                                        Keybind.Key = Input.KeyCode
                                        BindText.Text = "[ "..Library.Keys.KeyBoard[Input.KeyCode.Name][1].." ]"
                                        BindText.Position = Vector2.new(BindSensor.Position.X + (BindSensor.Size.X/2) - (BindText.TextBounds.X/2), ToggleText.Position.Y)
                                        Keybind.Picking = false
                                    end
                                end
                            end

                            -- << Key pressed >>
                            if Input.KeyCode == Keybind.Key then
                                Keybind.Callback()
                                Toggle.Toggled = not Toggle.Toggled
                                ToggleBackground.Color = Toggle.Toggled and Library.Theme.Accent[1] or Library.Theme.DarkContrast
                                ToggleText.Color = Toggle.Toggled and Library.Theme.DarkWhite or Library.Theme.DarkGrey
                                Keybind.State = 1
                            end
                        end)

                        Utility.AddConnection(UserInputService.InputEnded, function(Input)
                            if Input.KeyCode == Keybind.Key then
                                Keybind.State = 0
                            end
                        end)

                        function Keybind:GetState() -- 0 = not pressed, 1 = pressed (useful for binds which need to be held)
                            return Keybind.State
                        end

                        function Keybind:Get()
                            return Keybind.Key
                        end

                        function Keybind:Set(keycode)
                            Keybind.Key = keycode
                            if Library.Keys.KeyBoard[keycode.Name] then
                                if typeof(Library.Keys.KeyBoard[keycode.Name]) ~= "table" then
                                    Keybind.Key = keycode
                                    BindText.Text = "[ "..Library.Keys.KeyBoard[keycode.Name].." ]"
                                    BindText.Position = Vector2.new(BindSensor.Position.X + (BindSensor.Size.X/2) - (BindText.TextBounds.X/2), ToggleText.Position.Y)
                                    Keybind.Picking = false
                                else
                                    Keybind.Key = keycode
                                    BindText.Text = "[ "..Library.Keys.KeyBoard[keycode.Name][1].." ]"
                                    BindText.Position = Vector2.new(BindSensor.Position.X + (BindSensor.Size.X/2) - (BindText.TextBounds.X/2), ToggleText.Position.Y)
                                    Keybind.Picking = false
                                end
                            end
                        end

                        for i,v in pairs(Keybind.Drawings) do
                            Tab.Elements[#Tab.Elements+1] = v
                        end
                        return Keybind
                    end

                    function Toggle:Colorpicker(cprops)
                        cprops.Default = cprops.Default or {Color3.fromRGB(255, 0, 0), 1} -- { color, alpha }
                        cprops.Name = cprops.Name or "Colorpicker"
                        cprops.Flag = cprops.Flag or Utility.RandomString(15)
                        cprops.Callback = cprops.Callback or function() end
                        local Colorpicker = {
                            Drawings = {},
                            Window = {},
                            Color = cprops.Default[1],
                            Alpha = cprops.Default[2],
                            Hex = cprops.Default[1]:ToHex(),
                            Colors = {
                                HSV = {1, 1, 1},
                            },
                            Open = false,
                            Offsets = {
                                X = 0,
                                Y = 0
                            },
                            Dragging = {
                                Hue = false,
                                Saturation = false,
                                Transparency = false
                            }
                        }

                        local H, S, V = Colorpicker.Color:ToHSV()
                        Colorpicker.Colors.HSV[1] = H
                        Colorpicker.Colors.HSV[2] = S
                        Colorpicker.Colors.HSV[3] = V

                        local CPickerOutline = Utility.NewDrawing("Square", {
                            Position = ToggleOutline.Position + Vector2.new((SectionBackground.Size.X/2) + 53, 0),
                            Size = Vector2.new(20, 12),
                            Thickness = 0,
                            Color = Library.Theme.Outline,
                            Visible = false,
                            Filled = true
                        })
                        Colorpicker.Drawings.CPickerOutline = CPickerOutline

                        local CPickerInline = Utility.NewDrawing("Square", {
                            Position = CPickerOutline.Position + Vector2.new(1, 1),
                            Size = CPickerOutline.Size + Vector2.new(-2, -2),
                            Thickness = 0,
                            Color = Library.Theme.Inline,
                            Visible = false,
                            Filled = true
                        })
                        Colorpicker.Drawings.CPickerInline = CPickerInline

                        local CPickerBackground = Utility.NewDrawing("Square", {
                            Position = CPickerInline.Position + Vector2.new(1, 1),
                            Size = CPickerInline.Size + Vector2.new(-2, -2),
                            Thickness = 0,
                            Color = Colorpicker.Color,
                            Visible = false,
                            Filled = true
                        })
                        Colorpicker.Drawings.CPickerBackground = CPickerBackground

                        local CPickerGradient = Utility.NewDrawing("Image", {
                            Position = CPickerInline.Position + Vector2.new(1, 1),
                            Size = CPickerInline.Size + Vector2.new(-2, -2),
                            Data = Library.Images.GradientDown,
                            Visible = false,
                        })
                        Colorpicker.Drawings.CPickerGradient = CPickerGradient

                        function Colorpicker:MakeWindow()
                            local WindowOutline = Utility.NewDrawing("Square", {
                                Position = CPickerOutline.Position + Vector2.new(CPickerOutline.Size.X, 0),
                                Size = Vector2.new(170, 180),
                                Thickness = 0,
                                Color = Library.Theme.Outline,
                                Visible = false,
                                Filled = true
                            })
                            Colorpicker.Window.WindowOutline = WindowOutline
    
                            local WindowInline = Utility.NewDrawing("Square", {
                                Position = WindowOutline.Position + Vector2.new(1, 1),
                                Size = WindowOutline.Size + Vector2.new(-2, -2),
                                Thickness = 0,
                                Color = Library.Theme.Inline,
                                Visible = false,
                                Filled = true
                            })
                            Colorpicker.Window.WindowInline = WindowInline
    
                            local WindowBackground = Utility.NewDrawing("Square", {
                                Position = WindowInline.Position + Vector2.new(1, 1),
                                Size = WindowInline.Size + Vector2.new(-2, -2),
                                Thickness = 0,
                                Color = Library.Theme.DarkContrast,
                                Visible = false,
                                Filled = true
                            })
                            Colorpicker.Window.WindowBackground = WindowBackground

                            local WindowTopOutline = Utility.NewDrawing("Square", {
                                Position = WindowOutline.Position,
                                Size = Vector2.new(WindowOutline.Size.X, 20),
                                Thickness = 0,
                                Color = Library.Theme.Outline,
                                Visible = false,
                                Filled = true,
                            })
                            Colorpicker.Window.WindowTopOutline = WindowTopOutline

                            local WindowTopInline = Utility.NewDrawing("Square", {
                                Position = WindowTopOutline.Position + Vector2.new(1, 1),
                                Size = WindowTopOutline.Size + Vector2.new(-2, -2),
                                Thickness = 0,
                                Color = Library.Theme.Inline,
                                Visible = false,
                                Filled = true
                            })
                            Colorpicker.Window.WindowTopInline = WindowTopInline

                            local WindowTopBackground = Utility.NewDrawing("Square", {
                                Position = WindowTopInline.Position + Vector2.new(1, 1),
                                Size = WindowTopInline.Size + Vector2.new(-2, -2),
                                Thickness = 0,
                                Color = Library.Theme.DarkContrast,
                                Visible = false,
                                Filled = true
                            })
                            Colorpicker.Window.WindowTopBackground = WindowTopBackground

                            local TitleText = Utility.NewDrawing("Text", {
                                Font = Library.Theme.Font,
                                Size = Library.Theme.TextSize,
                                Color = Library.Theme.DarkWhite,
                                Text = cprops.Name,
                                Center = false,
                                Outline = true,
                                Visible = false,
                                Transparency = 1
                            })
                            Colorpicker.Window.TitleText = TitleText
                            TitleText.Position = Vector2.new(WindowTopOutline.Position.X + (WindowTopOutline.Size.X/2) - (TitleText.TextBounds.X/2), WindowTopOutline.Position.Y + 4)

                            local ValSatImage = Utility.NewDrawing("Image", {
                                Size = WindowOutline.Size + Vector2.new(-30, -(WindowTopOutline.Size.Y) - 25),
                                Position = WindowTopOutline.Position + Vector2.new(5, WindowTopOutline.Size.Y + 5),
                                Transparency = 1,
                                Visible = false,
                                Data = Library.Images.ValSat,
                                ZIndex = WindowBackground.ZIndex + 2
                            })
                            Colorpicker.Window.ValSatImage = ValSatImage

                            local ValSatColor = Utility.NewDrawing("Square", {
                                Size = ValSatImage.Size - Vector2.new(1, 0),
                                Position = ValSatImage.Position + Vector2.new(1, 0),
                                Transparency = 1,
                                Visible = false,
                                Color = Colorpicker.Color,
                                ZIndex = ValSatImage.ZIndex - 1,
                                Filled = true,
                                Thickness = 0
                            })
                            Colorpicker.Window.ValSatColor = ValSatColor

                            local AlphaImage = Utility.NewDrawing("Image", {
                                Size = Vector2.new(ValSatImage.Size.X, 10),
                                Position = ValSatImage.Position + Vector2.new(0, ValSatImage.Size.Y + 5),
                                Transparency = 1,
                                Visible = false,
                                Data = Library.Images.Transparency,
                                ZIndex = WindowBackground.ZIndex + 2
                            })
                            Colorpicker.Window.AlphaImage = AlphaImage

                            local HueImage = Utility.NewDrawing("Image", {
                                Size = Vector2.new(15, ValSatImage.Size.Y),
                                Position = ValSatImage.Position + Vector2.new(ValSatImage.Size.X + 5, 0),
                                Transparency = 1,
                                Visible = false,
                                Data = Library.Images.Hue,
                                ZIndex = WindowBackground.ZIndex + 2
                            })
                            Colorpicker.Window.HueImage = HueImage

                            Utility.AddDrag(WindowTopOutline, Colorpicker.Window)
                        end
                        Colorpicker:MakeWindow()

                        Colorpicker.Offsets.X = WindowBackground.Position.X
                        Colorpicker.Offsets.Y = WindowBackground.Position.Y
                        
                        function Colorpicker:RenderWindow()
                            if Colorpicker.Window.WindowOutline ~= nil then
                                for i,v in pairs(Colorpicker.Window) do
                                    v.Visible = true
                                end
                            end
                            Colorpicker.Open = true
                        end

                        function Colorpicker:DestroyWindow()
                            if Colorpicker.Window.WindowOutline ~= nil then
                                for i,v in pairs(Colorpicker.Window) do
                                    v.Visible = false
                                end
                            end
                            Colorpicker.Open = false
                        end

                        function Colorpicker:SetHue(Options)
                            local Percent = Options.Percent or Options.Value
                            local Wind = Colorpicker.Window

                            Colorpicker.Colors.HSV[1] = Options.Value

                            local HSVColor = Color3.fromHSV(Colorpicker.Colors.HSV[1], Colorpicker.Colors.HSV[2], Colorpicker.Colors.HSV[3])

                            --[[Wind.HuePickerOutline.Position = Wind.HueImage.Position + Vector2.new(-2, UserInputService:GetMouseLocation().Y) -- remove - 4
                            Wind.HuePicker.Position = Wind.HuePickerOutline.Position + Vector2.new(1, 1)]]

                            Wind.ValSatColor.Color = Color3.fromHSV(Colorpicker.Colors.HSV[1], 1, 1)
                            CPickerBackground.Color = Color3.fromHSV(Colorpicker.Colors.HSV[1], 1, 1)
                            Colorpicker.Color = HSVColor

                            cprops.Callback({Colorpicker.Color, Colorpicker.Alpha})
                        end

                        function Colorpicker:RefreshHue()
                            local Wind = Colorpicker.Window
                            local PercentHue = math.clamp(((Mouse.Y + 60) - Wind.HueImage.Position.Y) / (Wind.HueImage.Size.Y), 0, 1)
                            local ValueHue = math.floor((0 + (1 - 0) * PercentHue) * 50) / 50
                            ValueHue = math.clamp(ValueHue, 0, 1)
                            self:SetHue({
                                Value = ValueHue, 
                                Percent = PercentHue
                            })
                        end

                        function Colorpicker:SetSaturationX(Options)
                            local PercentX = Options.Percent or Options.Value

                            local HSVColor = Color3.fromHSV(Colorpicker.Colors.HSV[1], Colorpicker.Colors.HSV[2], Colorpicker.Colors.HSV[3])
                            Colorpicker.Colors.HSV[2] = Options.Value
                            
                            CPickerBackground.Color = HSVColor
                            Colorpicker.Color = HSVColor

                            cprops.Callback({Colorpicker.Color, Colorpicker.Alpha})
                        end

                        function Colorpicker:SetSaturationY(Options)
                            local PercentY = Options.Percent or 1 - Options.Value

                            local HSVColor = Color3.fromHSV(Colorpicker.Colors.HSV[1], Colorpicker.Colors.HSV[2], Colorpicker.Colors.HSV[3])
                            Colorpicker.Colors.HSV[3] = Options.Value
                            
                            CPickerBackground.Color = HSVColor
                            Colorpicker.Color = HSVColor

                            cprops.Callback({Colorpicker.Color, Colorpicker.Alpha})
                        end

                        function Colorpicker:RefreshSaturation()
                            local Wind = Colorpicker.Window
                            local PercentX = math.clamp((Mouse.X - Wind.ValSatImage.Position.X) / (Wind.ValSatImage.Size.X), 0, 1)
                            local ValueX = math.floor((1*PercentX) * 50) / 50
                            ValueX = math.clamp(ValueX, 0, 1)

                            Colorpicker:SetSaturationX({
                                Value = ValueX,
                                Percent = PercentX
                            })

                            local PercentY = math.clamp(((Mouse.Y + 60)-Wind.ValSatImage.Position.Y) / (Wind.ValSatImage.Size.Y), 0, 1)
                            local ValueY = math.floor((1-(1*PercentY)) * 50) / 50
                            ValueY = math.clamp(ValueY, 0, 1)

                            Colorpicker:SetSaturationY({
                                Value = ValueY,
                                Percent = PercentY
                            })
                        end

                        function Colorpicker:SetTransparency(Options)
                            local PercentX = Options.Percent or Options.Value

                            Colorpicker.Alpha = Options.Value

                            cprops.Callback({Colorpicker.Color, Colorpicker.Alpha})
                        end

                        function Colorpicker:RefreshTransparency()
                            local Wind = Colorpicker.Window

                            local PercentX = math.clamp((Mouse.X - Wind.AlphaImage.Position.X) / (Wind.AlphaImage.Size.X), 0, 1)
                            local ValueX = math.floor((1-(1*PercentX)) * 50) / 50

                            Colorpicker:SetTransparency({
                                Value = ValueX,
                                Percent = PercentX
                            })
                        end

                        Utility.AddConnection(UserInputService.InputEnded, function(Input)
                            if Input.UserInputType == Enum.UserInputType.MouseButton1 then
                                Colorpicker.Dragging.Hue = false
                                Colorpicker.Dragging.Transparency = false
                                Colorpicker.Dragging.Saturation = false
                            end
                        end)

                        Utility.AddConnection(UserInputService.InputChanged, function(Input)
                            if Input.UserInputType == Enum.UserInputType.MouseMovement then
                                if Colorpicker.Dragging.Hue then
                                    Colorpicker:RefreshHue()
                                elseif Colorpicker.Dragging.Saturation then
                                    Colorpicker:RefreshSaturation()
                                elseif Colorpicker.Dragging.Transparency then
                                    Colorpicker:RefreshTransparency()
                                end
                            end
                        end)

                        Utility.AddConnection(UserInputService.InputBegan, function(Input)
                            if Input.UserInputType == Enum.UserInputType.MouseButton1 and Utility.MouseOver(CPickerOutline) then
                                if Colorpicker.Open then
                                    Colorpicker.Open = not Colorpicker.Open
                                    Colorpicker:DestroyWindow()
                                else
                                    Colorpicker.Open = not Colorpicker.Open
                                    Colorpicker:RenderWindow()
                                end
                            end

                            if Input.UserInputType == Enum.UserInputType.MouseButton1 and Utility.MouseOver(Colorpicker.Window.HueImage) then
                                Colorpicker:RefreshHue()
                                Colorpicker.Dragging.Hue = true
                            end

                            if Input.UserInputType == Enum.UserInputType.MouseButton1 and Utility.MouseOver(Colorpicker.Window.ValSatImage) then
                                Colorpicker:RefreshSaturation()
                                Colorpicker.Dragging.Saturation = true
                            end

                            if Input.UserInputType == Enum.UserInputType.MouseButton1 and Utility.MouseOver(Colorpicker.Window.AlphaImage) then
                                Colorpicker:RefreshTransparency()
                                Colorpicker.Dragging.Transparency = true
                            end
                        end)

                        function Colorpicker:Get()
                            return {Colorpicker.Color, Colorpicker.Alpha}
                        end

                        function Colorpicker:Set(table)
                            -- TODO
                            Colorpicker.Color = table[1]
                            Colorpicker.Alpha = table[2]
                            cprops.Callback({Colorpicker.Color, Colorpicker.Alpha})
                        end

                        Colorpicker:SetHue({Value = Colorpicker.Colors.HSV[1]})
                        Colorpicker:SetSaturationX({Value = Colorpicker.Colors.HSV[2]})
                        Colorpicker:SetSaturationY({Value = Colorpicker.Colors.HSV[3]})

                        for i,v in pairs(Colorpicker.Drawings) do
                            Tab.Elements[#Tab.Elements+1] = v
                        end

                        Library.Flags[cprops.Flag] = Colorpicker
                        return Colorpicker
                    end

                    Library.Flags[eprops.Flag] = Toggle
                    return Toggle
                end

