                function Section:Slider(eprops)
                    eprops.Name = eprops.Name or "slider"
                    eprops.Color = eprops.Color or Library.Theme.DarkWhite
                    eprops.Callback = eprops.Callback or function() end
                    eprops.Min = eprops.Min or 0
                    eprops.Max = eprops.Max or 100
                    eprops.Default = eprops.Default or 35
                    eprops.Decimals = eprops.Decimals or 1
                    eprops.Symbol = eprops.Symbol or ""
                    eprops.Flag = eprops.Flag or Utility.RandomString(15)
                    local Slider = {
                        Axis = Section.ContentSize,
                        Drawings = {},
                        Dragging = false,
                        Value = eprops.Default
                    }

                    local SliderOutline = Utility.NewDrawing("Square", {
                        Position = Vector2.new(SectionBackground.Position.X + 8, SectionBackground.Position.Y + 25 + Slider.Axis),
                        Size = Vector2.new(SectionBackground.Size.X - 16, 8),
                        Thickness = 0,
                        Color = Library.Theme.Outline,
                        Visible = false,
                        Filled = true
                    })
                    Slider.Drawings.SliderOutline = SliderOutline

                    local SliderInline = Utility.NewDrawing("Square", {
                        Visible = false,
                        Transparency = 1,
                        Color = Library.Theme.Inline,
                        Size = SliderOutline.Size+Vector2.new(-2, -2),
                        Position = SliderOutline.Position+Vector2.new(1, 1),
                        Filled = true,
                    })
                    Slider.Drawings.SliderInline = SliderInline
            
                    local SliderBackground = Utility.NewDrawing("Square", {
                        Visible = false,
                        Transparency = 1,
                        Color = Library.Theme.Background,
                        Size = SliderInline.Size+Vector2.new(-2, -2),
                        Position = SliderInline.Position+Vector2.new(1, 1),
                        Filled = true,
                    })
                    Slider.Drawings.SliderBackground = SliderBackground

                    local SliderFill = Utility.NewDrawing("Square", {
                        Visible = false,
                        Transparency = 1,
                        Color = Library.Theme.Inline,
                        Size = Vector2.new(SliderBackground.Size.X/2, SliderBackground.Size.Y),
                        Position = SliderInline.Position+Vector2.new(1, 1),
                        Filled = true,
                    })
                    Slider.Drawings.SliderFill = SliderFill

                    local SliderGradient = Utility.NewDrawing("Image", {
                        Visible = false,
                        Transparency = 1,
                        Size = SliderInline.Size+Vector2.new(-2, -2),
                        Position = SliderInline.Position+Vector2.new(1, 1),
                        Data = Library.Images.GradientDown
                    })
                    Slider.Drawings.SliderGradient = SliderGradient

                    local SliderTitle = Utility.NewDrawing("Text", {
                        Font = Library.Theme.Font,
                        Size = Library.Theme.TextSize,
                        Color = eprops.Color,
                        Text = eprops.Name,
                        Center = false,
                        Outline = true,
                        Visible = false,
                        Transparency = 1
                    })
                    SliderTitle.Position = Vector2.new(SliderOutline.Position.X + 3, SliderOutline.Position.Y - 11)
                    Slider.Drawings.SliderTitle = SliderTitle

                    local SliderText = Utility.NewDrawing("Text", {
                        Font = Library.Theme.Font,
                        Size = Library.Theme.TextSize,
                        Color = eprops.Color,
                        Center = false,
                        Outline = true,
                        Visible = false,
                        Transparency = 1
                    })
                    Slider.Drawings.SliderText = SliderText
                    SliderText.Text = Utility.ParseTriggers(tostring(eprops.Default).." "..eprops.Symbol.." / "..tostring(eprops.Max).." "..eprops.Symbol)
                    SliderText.Position = Vector2.new(SliderOutline.Position.X + SliderOutline.Size.X - SliderText.TextBounds.X, SliderOutline.Position.Y - 11)

                    Section.ContentSize = Section.ContentSize + SliderOutline.Size.Y + 16
                    Tab.Sections[props.Side] = Tab.Sections[props.Side] + SliderOutline.Size.Y+ 16 or Tab.Sections[props.Side]

                    self:UpdateSizeY(Section.ContentSize + SliderOutline.Size.Y + 8)

                    for i,v in pairs(Slider.Drawings) do
                        Tab.Elements[#Tab.Elements+1] = v
                    end

                    function Slider:Set(value)
                        if value > eprops.Max then return end
                        if value < eprops.Min then return end
                        
                        local Bracket = 1 / eprops.Decimals
                        local DecimalsCon = math.clamp(math.round(value * Bracket) / Bracket, eprops.Min, eprops.Max)
                        local Percent = 1 - ((eprops.Max - DecimalsCon) / (eprops.Max - eprops.Min))
                        SliderFill.Size = Vector2.new(SliderBackground.Size.X * Percent, SliderBackground.Size.Y)
                        SliderText.Text = ("%s %s / %s %s"):format(DecimalsCon, eprops.Symbol, eprops.Max, eprops.Symbol)
                        SliderText.Position = Vector2.new(SliderOutline.Position.X + SliderOutline.Size.X - SliderText.TextBounds.X, SliderOutline.Position.Y - 11)
                        
                        eprops.Callback(value)
                    end

                    function Slider:Get()
                        return Slider.Value
                    end

                    function Slider:Refresh()
                        local Percent = math.clamp((Mouse.X - SliderOutline.Position.X) / (SliderOutline.Size.X), 0, 1)
                        local Bracket = 1 / eprops.Decimals
                        local Value = math.floor((eprops.Min + (eprops.Max - eprops.Min) * Percent) * Bracket) / Bracket
                        Value = math.clamp(Value, eprops.Min, eprops.Max)
                        Slider.Value = Value

                        Slider:Set(Value)
                    end

                    Utility.AddConnection(UserInputService.InputBegan, function(Input)
                        if Input.UserInputType == Enum.UserInputType.MouseButton1 and Utility.MouseOver(SliderOutline) then
                            Slider:Refresh()
                            Slider.Dragging = true
                        end
                    end)
                    
                    Utility.AddConnection(UserInputService.InputEnded, function(Input)
                        if Input.UserInputType == Enum.UserInputType.MouseButton1 then
                            Slider.Dragging = false
                        end
                    end)
                    
                    Utility.AddConnection(UserInputService.InputChanged, function(Input)
                        if Utility.MouseOver(SliderInline) then
                            SliderFill.Color = Library.Theme.Accent[1]
                        else
                            SliderFill.Color = Library.Theme.Inline
                        end
        
                        if Input.UserInputType == Enum.UserInputType.MouseMovement and Slider.Dragging then
                            Slider:Refresh()
                        end
                    end)

                    Slider:Set(eprops.Default)

                    Library.Flags[eprops.Flag] = Slider

                    return Slider
                end

