                        })
                        Item.ButtonText = ButtonText
                        ButtonText.Position = Vector2.new(ButtonOutline.Position.X + (ButtonOutline.Size.X/2)-(ButtonText.TextBounds.X/2), ButtonOutline.Position.Y + 3)

                        Utility.AddConnection(UserInputService.InputBegan, function(Input)
                            if Input.UserInputType == Enum.UserInputType.MouseButton1 and Utility.MouseOver(ButtonOutline, true) then
                                Dropdown:Set(Dropdown.List[item])
                                for i, v in pairs(Dropdown.Buttons) do
                                    v.ButtonText.Color = eprops.Color
                                end
                                ButtonText.Color = Library.Theme.Accent[1]
                            end
                        end)

                        Dropdown.Buttons[#Dropdown.Buttons+1] = Item
                        return Item
                    end

                    function Dropdown:Refresh(list)
                        -- TODO
                    end

                    function Dropdown:Get()
                        return Dropdown.Selected
                    end

                    function Dropdown:Set(value)
                        Dropdown.Selected = value
                        DropdownText.Text = Dropdown.Selected
                        DropdownText.Position = Vector2.new(DropdownOutline.Position.X + (DropdownOutline.Size.X/2)-(DropdownText.TextBounds.X/2), DropdownOutline.Position.Y + 3)
                        eprops.Callback(Dropdown.Selected)
                    end
                
                    Section.ContentSize = Section.ContentSize + DropdownOutline.Size.Y + 12 + 10
                    Tab.Sections[props.Side] = Tab.Sections[props.Side] + DropdownOutline.Size.Y + 10 + 2 or Tab.Sections[props.Side]
                
                    self:UpdateSizeY(Section.ContentSize + DropdownOutline.Size.Y - 5)
                
                    for i,v in pairs(Dropdown.Drawings) do
                        Tab.Elements[#Tab.Elements+1] = v
                    end

                    for index, item in pairs(Dropdown.List) do
                        Dropdown:Insert(index)
                    end

                    Utility.AddConnection(UserInputService.InputBegan, function(Input)
                        if Input.UserInputType == Enum.UserInputType.MouseButton1 and Utility.MouseOver(DropdownOutline, true) then
                            Dropdown.Open = not Dropdown.Open
                            DropdownFrameOutline.Visible = Dropdown.Open
                            DropdownFrameInline.Visible = Dropdown.Open
                            DropdownFrameBackground.Visible = Dropdown.Open
                            DropdownButton.Text = Dropdown.Open and "-" or "+"

                            for i, v in pairs(Dropdown.Buttons) do
                                v.ButtonOutline.Visible = Dropdown.Open
                                v.ButtonInline.Visible = Dropdown.Open
                                v.ButtonBackground.Visible = Dropdown.Open
                                v.ButtonText.Visible = Dropdown.Open
                            end

                            Library.DropdownOpen = Dropdown.Open
                        end
                    end)

                    Library.Flags[eprops.Flag] = Dropdown

                    return Dropdown
                end

                Tab.Sections[props.Side] += SectionOutline.Size.Y
                for i,v in pairs(Section.Drawings) do
                    Tab.Elements[#Tab.Elements+1] = v
                end
                return Section
            end

            if Tab.Selected then
                TabText.Color = Library.Theme.Accent[1]
                TabBackground.Color = Library.Theme.Background
                for i,v in pairs(Tab.Elements) do
                    v.Visible = true
                end
            end
            table.insert(Window.Tabs, Tab)
            return Tab
        end

        function Window:Notify(eprops)
            eprops.Color = eprops.Color or Library.Theme.DarkWhite
            eprops.Text = eprops.Text or "n o t i f i c a t i o n"
            eprops.Time = eprops.Time or 5
            
            local NotificationOutline = Utility.NewDrawing("Square", {
                Visible = true,
                Transparency = 1,
                Color = Library.Theme.Outline,
                Size = Vector2.new(370, 20),
                Filled = true,
            }, Library.Special.Notifications)
        
            local NotificationInline = Utility.NewDrawing("Square", {
                Visible = true,
                Transparency = 1,
                Color = Library.Theme.Inline,
                Size = NotificationOutline.Size+Vector2.new(-2, -2),
                Position = NotificationOutline.Position+Vector2.new(1, 1),
                Filled = true,
            }, Library.Special.Notifications)
        
            local NotificationBackground = Utility.NewDrawing("Square", {
                Visible = true,
                Transparency = 1,
                Color = Library.Theme.Background,
                Size = NotificationInline.Size+Vector2.new(-2, -2),
                Position = NotificationInline.Position+Vector2.new(1, 1),
                Filled = true,
            }, Library.Special.Notifications)
        
            local NotificationText = Utility.NewDrawing("Text", {
                Font = Library.Theme.Font,
                Size = Library.Theme.TextSize,
                Color = Library.Theme.DarkWhite,
                Center = false,
                Outline = true,
                Visible = true,
                Transparency = 1
            }, Library.Special.Notifications)
            NotificationText.Text = Utility.ParseTriggers("{time}  |  "..eprops.Text)
            NotificationText.Color = eprops.Color

            NotificationOutline.Size = Vector2.new(NotificationText.TextBounds.X+15, 20)
            NotificationInline.Size = NotificationOutline.Size+Vector2.new(-2, -2)
            NotificationBackground.Size = NotificationInline.Size+Vector2.new(-2, -2)

            NotificationOutline.Position = Vector2.new(Camera.ViewportSize.X, 50) - Vector2.new(NotificationOutline.Size.X + 10, 0)
            NotificationInline.Position = NotificationOutline.Position + Vector2.new(1, 1)
            NotificationBackground.Position = NotificationInline.Position + Vector2.new(1, 1)
            NotificationText.Position = NotificationBackground.Position + Vector2.new(5, 2)
            
            Window.Notifications += NotificationOutline.Size.Y
            Library.Communication.Other:Fire("NotifCreate")

            task.spawn(function()
                task.wait(5)
                NotificationOutline:Destroy()
                NotificationInline:Destroy()
                NotificationBackground:Destroy()
                NotificationText:Destroy()
            end)

            Utility.AddConnection(Library.Communication.Other.Event, function(Type)
                if Type == "NotifCreate" then
                    NotificationOutline.Position = NotificationOutline.Position + Vector2.new(0, NotificationOutline.Size.Y)
                    NotificationInline.Position = NotificationOutline.Position + Vector2.new(1, 1)
                    NotificationBackground.Position = NotificationInline.Position + Vector2.new(1, 1)
                    NotificationText.Position = NotificationBackground.Position + Vector2.new(5, 2)
                end
            end)
        end

        function Window:Fade(bool)
            bool = bool or false

            for i, v in pairs(Library.Drawings) do
                if bool then
                    task.spawn(function()
                        for i = 1, 0, -0.025 do
                            task.wait()
                            v.Transparency = v.Transparency - 0.025
                        end
                    end)
                else
                    task.spawn(function()
                        for i = 1, 0, -0.025 do
                            task.wait()
                            v.Transparency = v.Transparency + 0.025
                        end
                    end)
                end
            end
        end

        Utility.AddConnection(UserInputService.InputBegan, function(Input)
            if Input.KeyCode == Enum.KeyCode.Z then
                Window:Fade(Library.WindowVisible)
                Library.WindowVisible = not Library.WindowVisible
                UserInputService.MouseIconEnabled = not Library.WindowVisible
            end
        end)

        -- << Configs >>

        function Window:GetConfig()
            local flag_values = {}

            for i, v in pairs(Library.Flags) do
                flag_values[i] = v:Get()
            end

            return HttpService:JSONEncode(flag_values)
        end

        function Window:LoadConfig(encoded_config)
            local flags = HttpService:JSONDecode(encoded_config)

            for i, v in pairs(flags) do
                Library.Flags[i]:Set(v)
            end
        end

        UserInputService.MouseIconEnabled = Library.WindowVisible
        return Window
    end

    Utility.DrawCursor()
end

return {Library, Utility}
